long long largestRectangleArea(vector<int> h) {
    h.push_back(0);                       // SENTINEL: forces the stack to fully drain
    stack<int> st;                        // indices, increasing height
    long long best = 0;
    for (int i = 0; i < (int)h.size(); ++i) {
        while (!st.empty() && h[st.top()] >= h[i]) {
            int height = h[st.top()]; st.pop();
            // left boundary is the new top (EXCLUSIVE), right boundary is i (EXCLUSIVE)
            int left = st.empty() ? -1 : st.top();
            long long width = i - left - 1;
            best = max(best, (long long)height * width);
        }
        st.push(i);
    }
    return best;
}

int maximalRectangle(const vector<vector<char>>& mat) {
    if (mat.empty() || mat[0].empty()) return 0;
    int cols = (int)mat[0].size();
    vector<int> heights(cols, 0);
    int best = 0;
    for (const auto& row : mat) {
        for (int j = 0; j < cols; ++j)
            heights[j] = (row[j] == '1') ? heights[j] + 1 : 0;   // RESET on a zero
        best = max(best, (int)largestRectangleArea(heights));
    }
    return best;
}

