int longestValidParentheses(const string& s) {
    stack<int> st;
    st.push(-1);                          // BARRIER: base index for the first valid run
    int best = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '(') { st.push(i); continue; }
        st.pop();
        if (st.empty()) st.push(i);       // unmatched ')': it becomes the new barrier
        else            best = max(best, i - st.top());
    }
    return best;
}

// O(1) SPACE: count both directions. One pass alone misses asymmetric strips.
int longestValidParenthesesO1(const string& s) {
    int best = 0, open = 0, close = 0;
    for (char c : s) {                    // left to right catches ")" excess
        (c == '(') ? ++open : ++close;
        if (open == close)      best = max(best, 2 * close);
        else if (close > open)  open = close = 0;
    }
    open = close = 0;
    for (int i = (int)s.size() - 1; i >= 0; --i) {   // right to left catches "(" excess
        (s[i] == '(') ? ++open : ++close;
        if (open == close)      best = max(best, 2 * open);
        else if (open > close)  open = close = 0;
    }
    return best;
}

