def longest_valid_parentheses_o1(s: str) -> int:
    """O(1) SPACE: count both directions. One pass alone misses asymmetric strips."""
    best = open_c = close_c = 0
    for c in s:                            # left to right catches ")" excess
        if c == "(":
            open_c += 1
        else:
            close_c += 1
        if open_c == close_c:
            best = max(best, 2 * close_c)
        elif close_c > open_c:
            open_c = close_c = 0

    open_c = close_c = 0
    for c in reversed(s):                  # right to left catches "(" excess
        if c == "(":
            open_c += 1
        else:
            close_c += 1
        if open_c == close_c:
            best = max(best, 2 * open_c)
        elif open_c > close_c:
            open_c = close_c = 0
    return best

