vector<int> asteroidCollision(const vector<int>& a) {
    vector<int> st;
    for (int x : a) {
        bool alive = true;
        // collision ONLY when the stack top moves right and x moves left
        while (alive && x < 0 && !st.empty() && st.back() > 0) {
            if (st.back() < -x)       { st.pop_back(); continue; }  // top dies, keep checking
            if (st.back() == -x)      { st.pop_back(); }            // BOTH die
            alive = false;                                          // x dies either way
        }
        if (alive) st.push_back(x);
    }
    return st;
}

