    st = []
    for x in a:
        alive = True
        # collision ONLY when the stack top moves right and x moves left
        while alive and x < 0 and st and st[-1] > 0:
            if st[-1] < -x:
                st.pop()          # top dies, keep checking further down
                continue
            if st[-1] == -x:
                st.pop()          # BOTH die
            alive = False         # x dies either way
        if alive:
            st.append(x)
    return st

