string removeKdigits(const string& num, int k) {
    string st;
    for (char c : num) {
        // a larger digit in a MORE significant place always hurts: drop it
        while (k > 0 && !st.empty() && st.back() > c) { st.pop_back(); --k; }
        st.push_back(c);
    }
    while (k-- > 0 && !st.empty()) st.pop_back();     // budget left: trim the tail
    int i = 0;
    while (i < (int)st.size() && st[i] == '0') ++i;    // strip leading zeros
    string out = st.substr(i);
    return out.empty() ? "0" : out;                    // never return an empty string
}

