def remove_k_digits(num: str, k: int) -> str:
    st = []
    for c in num:
        # a larger digit in a MORE significant place always hurts: drop it
        while k > 0 and st and st[-1] > c:
            st.pop()
            k -= 1
        st.append(c)
    while k > 0 and st:
        st.pop()                       # budget left: trim the tail
        k -= 1
    out = "".join(st).lstrip("0")
    return out if out else "0"         # never return an empty string

