string decodeString(const string& s) {
    stack<int> counts;
    stack<string> prefixes;
    string cur;
    int num = 0;
    for (char c : s) {
        if (isdigit((unsigned char)c)) {
            num = num * 10 + (c - '0');       // MULTI-DIGIT: 12[a] is twelve, not 1 then 2
        } else if (c == '[') {
            counts.push(num);                 // park the count and the prefix
            prefixes.push(cur);
            num = 0; cur.clear();
        } else if (c == ']') {
            string repeated;
            repeated.reserve(cur.size() * counts.top());
            for (int i = 0; i < counts.top(); ++i) repeated += cur;
            counts.pop();
            cur = prefixes.top() + repeated;  // restore the prefix, append the expansion
            prefixes.pop();
        } else {
            cur += c;
        }
    }
    return cur;
}

