def decode_string(s: str) -> str:
    counts, prefixes = [], []
    cur, num = [], 0
    for c in s:
        if c.isdigit():
            num = num * 10 + int(c)      # MULTI-DIGIT: 12[a] is twelve, not 1 then 2
        elif c == "[":
            counts.append(num)           # park the count and the prefix
            prefixes.append(cur)
            num, cur = 0, []
        elif c == "]":
            repeated = "".join(cur) * counts.pop()
            cur = prefixes.pop()
            cur.append(repeated)         # restore the prefix, append the expansion
        else:
            cur.append(c)
    return "".join(cur)

