// NEXT smaller to the RIGHT (strict). Pop while top is GREATER than current.
vector<int> nextSmallerRight(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, -1);
    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] > a[i]) { out[st.top()] = a[i]; st.pop(); }
        st.push(i);
    }
    return out;
}

// PREVIOUS smaller to the LEFT (strict). Same loop, read the surviving top.
vector<int> prevSmallerLeft(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, -1);
    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        out[i] = st.empty() ? -1 : a[st.top()];
        st.push(i);
    }
    return out;
}

// NON-STRICT variant: >= instead of > changes who wins a TIE.
// Ties matter: for contribution counting (K401) exactly ONE side must be
// non-strict, or equal elements double-count the spans between them.
vector<int> nextSmallerOrEqualRight(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, -1);
    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] >= a[i]) { out[st.top()] = a[i]; st.pop(); }
        st.push(i);
    }
    return out;
}
